mapper.select:
SELECT *
FROM t_solvela_job_log


        AND ( INSTR(job_name,#{query.searchWord})
        OR INSTR(param_snapshot,#{query.searchWord})
        OR INSTR(result_summary,#{query.searchWord})
        OR INSTR(trace_id,#{query.searchWord})
        OR INSTR(create_name,#{query.searchWord})
        )


        AND job_id = #{query.jobId}


        AND status = #{query.status}


        AND trigger_source = #{query.triggerSource}


        AND DATE_FORMAT(execute_start_time, '%Y-%m-%d') >= #{query.startTime}


        AND DATE_FORMAT(execute_start_time, '%Y-%m-%d') <= #{query.endTime}



    ORDER BY log_id DESC

SELECT *
FROM t_solvela_job_log
WHERE app_env = #{appEnv}
  AND status = 0
  AND fire_time IS NOT NULL
  AND fire_time <= #{dbNow}
ORDER BY fire_time
LIMIT #{limit}

SELECT COUNT(1)
FROM t_solvela_job_log
WHERE job_id = #{jobId}
AND status = 1
AND execute_start_time >= #{earliestStartTime}


    AND log_id != #{excludeLogId}

SELECT *
FROM t_solvela_job_log
WHERE status = 1
  AND execute_start_time < #{beforeTime}
ORDER BY log_id
LIMIT #{limit}

mapper.delete:
DELETE
FROM t_solvela_job_log
WHERE create_time < #{beforeTime}
LIMIT #{limit}
